NEW_BODY = INTRO + GENERAL_PART_PURPOSE + ANALYSIS_TECH + CHOICE_TOOLS + DEVELOPMENT + CONCLUSION + SOURCES
print(f"Total new paragraphs: {len(NEW_BODY)}")

# === FIND BODY BOUNDARIES ===
# Body starts at paragraph "ВВЕДЕНИЕ" and ends at the last source entry.
# Find index of ВВЕДЕНИЕ as first replaceable paragraph
paragraphs = doc.paragraphs
start_idx = None
end_idx = None
for i, par in enumerate(paragraphs):
    t = par.text.strip()
    if start_idx is None and t == "ВВЕДЕНИЕ":
        start_idx = i
    if start_idx is not None:
        # last paragraph that should be replaced — last reference entry of the original
        end_idx = i  # we'll keep updating to end of file
print(f"Body region: paragraphs[{start_idx}:{end_idx+1}], total={end_idx-start_idx+1} old paragraphs")

# === HELPERS ===
def clear_runs(par):
    for r in list(par.runs):
        r._r.getparent().remove(r._r)

def apply_block(par, style_name, text, bold, size_pt):
    # Set the paragraph style
    if style_name and style_name in [s.name for s in doc.styles]:
        par.style = doc.styles[style_name]
    clear_runs(par)
    run = par.add_run(text)
    if bold is not None:
        run.bold = bold
    if size_pt is not None:
        run.font.size = Pt(size_pt)

def insert_new_paragraph_after(par, style_name):
    """Create a new <w:p> right after the given paragraph and return its Paragraph object."""
    new_p = deepcopy(par._p)
    # Strip all runs from the copy
    for r in new_p.findall(qn("w:r")):
        new_p.remove(r)
    # Also strip pPr children that may have style — we'll reset
    par._p.addnext(new_p)
    # Wrap into Paragraph object
    from docx.text.paragraph import Paragraph
    return Paragraph(new_p, par._parent)

def delete_paragraph(par):
    par._element.getparent().remove(par._element)

# === REWRITE ===
# Step 1: replace existing paragraphs from start_idx in-place with our content.
# Step 2: if our content has more paragraphs, insert new ones after the last.
# Step 3: if our content has fewer, delete the leftover paragraphs.

body = doc.paragraphs  # snapshot
# Anchor list of existing paragraphs we'll work with
anchors = body[start_idx:end_idx + 1]

# Fill anchors with our content
n_overlap = min(len(anchors), len(NEW_BODY))
for i in range(n_overlap):
    style_name, text, bold, size_pt = NEW_BODY[i]
    apply_block(anchors[i], style_name, text, bold, size_pt)

# If new body has extra paragraphs — insert after the last anchor
if len(NEW_BODY) > len(anchors):
    last = anchors[-1]
    for i in range(n_overlap, len(NEW_BODY)):
        style_name, text, bold, size_pt = NEW_BODY[i]
        new_par = insert_new_paragraph_after(last, style_name)
        apply_block(new_par, style_name, text, bold, size_pt)
        last = new_par

# If new body is shorter — delete leftover anchors
elif len(NEW_BODY) < len(anchors):
    for par in anchors[n_overlap:]:
        delete_paragraph(par)

doc.save(DST)
print(f"Saved: {DST}")
print(f"Final paragraph count in body region: {len(NEW_BODY)}")
